function molality(molesSolute, kgSolvent){ if(!(kgSolvent>0)) return NaN; return molesSolute/kgSolvent; } // mol/kg
function molarityToMolality(M, density, molarMass){ // M mol/L solution, density kg/L solution, molarMass g/mol
  if(!(density>0)||!(M>0)||!(molarMass>0)) return NaN;
  var kgSolventPerL = density - (M*molarMass/1000); // 1 L solution minus solute mass
  if(kgSolventPerL<=0) return NaN;
  return M/kgSolventPerL;
}
var EXPORTS = { molality:molality, molarityToMolality:molarityToMolality };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MolalityForgePure = EXPORTS; }
